<script setup lang="ts">
import { computed, onMounted, ref } from "vue";
import { http } from "@/utils/http";
type Task = { id: string; title: string; status?: string; priority?: string; important?: boolean; urgent?: boolean; scheduledStart?: string; deadline?: string; estimatedDurationMinutes?: number; version?: number };
const inbox = ref<Task[]>([]); const today = ref<Task[]>([]); const loading = ref(false); const saving = ref(false); const error = ref(""); const dialog = ref(false); const form = ref({ title: "", priority: "MEDIUM", important: false, urgent: false });
const overdue = computed(() => today.value.filter(task => task.deadline && new Date(task.deadline) < new Date() && task.status !== "COMPLETED")); const scheduled = computed(() => today.value.filter(task => task.scheduledStart && !overdue.value.includes(task) && task.status !== "COMPLETED")); const unscheduled = computed(() => today.value.filter(task => !task.scheduledStart && !overdue.value.includes(task) && task.status !== "COMPLETED")); const completed = computed(() => today.value.filter(task => task.status === "COMPLETED"));
async function load() { loading.value = true; error.value = ""; try { const [all, current] = await Promise.all([http.get<unknown, unknown>("/planning/tasks"), http.get<unknown, unknown>("/planning/tasks/today")]); inbox.value = Array.isArray(all) ? all as Task[] : []; today.value = Array.isArray(current) ? current as Task[] : []; } catch (e: any) { error.value = e?.response?.data?.detail || e?.message || "任务加载失败"; } finally { loading.value = false; } }
async function addTask() { if (!form.value.title.trim()) { error.value = "任务标题不能为空"; return; } saving.value = true; try { await http.post("/planning/tasks", { data: { ...form.value, title: form.value.title.trim() } }); dialog.value = false; form.value = { title: "", priority: "MEDIUM", important: false, urgent: false }; await load(); } catch (e: any) { error.value = e?.response?.data?.detail || e?.message || "任务创建失败"; } finally { saving.value = false; } }
async function complete(task: Task) { try { await http.post(`/planning/tasks/${task.id}/status/COMPLETED`, { headers: task.version == null ? undefined : { "If-Match": `\"${task.version}\"` } }); await load(); } catch (e: any) { error.value = e?.response?.data?.detail || e?.message || "任务状态更新失败"; } }
onMounted(load);
</script>
<template><main class="p-4 md:p-6"><div class="flex justify-between items-start gap-4 mb-6"><div><h1 class="text-2xl font-semibold">收集箱与今天</h1><p class="mt-1 text-[var(--el-text-color-secondary)]">快速捕获任务，再将重要事项安排到今天。</p></div><div class="flex gap-2"><el-button @click="dialog = true">添加任务</el-button><el-button plain @click="load">规划今天</el-button></div></div><el-alert v-if="error" :title="error" type="error" show-icon :closable="false" class="mb-4"/><el-skeleton v-if="loading" :rows="10" animated/><div v-else class="grid grid-cols-1 lg:grid-cols-5 gap-5"><el-card shadow="never" class="lg:col-span-2"><template #header><div class="flex justify-between"><span class="font-medium">收集箱</span><el-tag>{{ inbox.length }}</el-tag></div></template><el-empty v-if="!inbox.length" description="收集箱为空"/><div v-for="task in inbox" :key="task.id" class="flex items-center gap-2 py-3 border-b last:border-0"><el-checkbox :model-value="task.status === 'COMPLETED'" @change="complete(task)"/><span class="flex-1 truncate">{{ task.title }}</span><el-tag v-if="task.urgent" type="danger" size="small">紧急</el-tag></div></el-card><el-card shadow="never" class="lg:col-span-3"><template #header><div class="flex justify-between"><span class="font-medium">今天 · {{ new Date().toLocaleDateString() }}</span><el-button link @click="load">刷新</el-button></div></template><div v-for="group in [{ label: '已逾期', items: overdue }, { label: '已安排', items: scheduled }, { label: '未安排', items: unscheduled }]" :key="group.label" class="mb-5"><div class="text-sm font-medium mb-2">{{ group.label }}（{{ group.items.length }}）</div><el-empty v-if="!group.items.length" :description="`暂无${group.label}任务`" :image-size="48"/><div v-for="task in group.items" :key="task.id" class="flex items-center gap-2 py-2 border-b"><el-checkbox @change="complete(task)"/><span class="flex-1">{{ task.title }}</span><el-tag v-if="task.priority" size="small">{{ task.priority }}</el-tag><span class="text-xs text-[var(--el-text-color-secondary)]">{{ task.estimatedDurationMinutes ? `${task.estimatedDurationMinutes} 分钟` : '' }}</span></div></div><el-collapse><el-collapse-item title="已完成" name="completed"><div v-for="task in completed" :key="task.id" class="py-2 line-through text-[var(--el-text-color-secondary)]">{{ task.title }}</div><el-empty v-if="!completed.length" description="暂无已完成任务" :image-size="48"/></el-collapse-item></el-collapse></el-card></div><el-dialog v-model="dialog" title="添加任务" width="480px"><el-form label-position="top"><el-form-item label="标题" required><el-input v-model="form.title" @keyup.enter="addTask"/></el-form-item><el-form-item label="优先级"><el-select v-model="form.priority" class="w-full"><el-option label="低" value="LOW"/><el-option label="中" value="MEDIUM"/><el-option label="高" value="HIGH"/></el-select></el-form-item><el-form-item><el-checkbox v-model="form.important">重要</el-checkbox><el-checkbox v-model="form.urgent">紧急</el-checkbox></el-form-item></el-form><template #footer><el-button @click="dialog = false">取消</el-button><el-button type="primary" :loading="saving" @click="addTask">创建</el-button></template></el-dialog></main></template>
